SELECT event_date, campaign_id, impressions, clicks, ctr
FROM agg_campaign_daily
WHERE event_date = DATE '2017-05-12' AND campaign_id = 187911;

SELECT event_date, campaign_id, impressions, clicks, ctr
FROM agg_campaign_daily_valid
WHERE event_date = DATE '2017-05-12' AND campaign_id = 55121;

SELECT COUNT(DISTINCT user_id) AS distinct_clickers
FROM fact_ad_events
WHERE is_click = 1;

SELECT campaign_id, impressions, clicks, ctr
FROM live_campaign_last6h
WHERE campaign_id = 372278;

SELECT campaign_id, clicks
FROM live_campaign_last6h
WHERE campaign_id = 8777;

SELECT COUNT(DISTINCT user_id) AS distinct_clickers
